DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `CariReason` (IN `p_keyword` VARCHAR(255))   BEGIN
    SELECT 
        id_izin_keluar,
        id_siswa,
        start_date,
        end_date,
        reason,
        status_approval
    FROM leave_requests 
    WHERE reason COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_keyword, '%') COLLATE utf8mb4_unicode_ci;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `HitungIzinSiswa` (IN `p_id_siswa` INT, OUT `p_total_izin` INT)   BEGIN
    -- Menghitung jumlah data dan memasukkannya ke variabel OUT
    SELECT COUNT(*) INTO p_total_izin 
    FROM leave_requests 
    WHERE id_siswa = p_id_siswa;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `KaliTotalIzin` (INOUT `p_angka` INT)   BEGIN
    DECLARE v_jumlah_data INT;

    -- Mengambil total baris data dari tabel leave_requests
    SELECT COUNT(*) INTO v_jumlah_data FROM leave_requests;

    -- Mengalikan nilai input awal dengan jumlah data, lalu menimpanya kembali ke parameter
    SET p_angka = p_angka * v_jumlah_data;
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `HitungLamaHari` (`p_start` DATE, `p_end` DATE) RETURNS INT DETERMINISTIC BEGIN
    DECLARE jumlah_hari INT;
    SET jumlah_hari = DATEDIFF(p_end, p_start) + 1;
    RETURN jumlah_hari;
END$$

